def connection_settings(env):
    required = {"PGHOST": "host", "PGDATABASE": "dbname", "PGUSER": "user", "PGPASSWORD": "password"}
    missing = sorted(name for name in required if name not in env)
    if missing:
        raise KeyError("missing: " + ", ".join(missing))
    settings = {key: env[name] for name, key in required.items()}
    settings["port"] = int(env.get("PGPORT", 5432))
    return settings

full = {"PGHOST": "db", "PGDATABASE": "warehouse", "PGUSER": "etl", "PGPASSWORD": "s3cret"}
settings = connection_settings(full)
print(dict(sorted({**settings, "password": "***"}.items())))
try:
    connection_settings({"PGUSER": "etl"})
except KeyError as err:
    print(err.args[0])
